  if(Path.GetExtension(target.Path).ToLowerInvariant() is not(".jpg" or ".jpeg" or ".png" or ".bmp"))return "仅支持8位JPEG / PNG / BMP";
  if(source.FrozenVariant.Stack?.Graph is not null)return "当前后端不接复杂节点图";
  if(source.FrozenVariant.Stack?.Nodes.Any(n=>n.Type==ColorStudioNodeType.Film)==true||source.FrozenVariant.Film?.Enabled==true)return "来源已含胶片效果";
  return await Task.Run(()=>{token.ThrowIfCancellationRequested();using var file=File.OpenRead(target.Path);var header=BitmapDecoder.Create(file,BitmapCreateOptions.DelayCreation|BitmapCreateOptions.IgnoreColorProfile,BitmapCacheOption.OnDemand).Frames[0];if(header.Format.BitsPerPixel>32)return "当前后端不接16位 / 浮点输入";if(Path.GetExtension(target.Path).Equals(".png",StringComparison.OrdinalIgnoreCase)){Span<byte> bytes=stackalloc byte[29];file.Position=0;file.ReadExactly(bytes);if(bytes[24]>8)return "当前后端不接16位输入";}var required=checked((long)header.PixelWidth*header.PixelHeight*8);if(required>256L*1024*1024)return "预检超过预算";using var previewBudget=StudioGlobalResources.ReserveWork(required);var image=StudioQuickExport.Load(target.Path);token.ThrowIfCancellationRequested();var rgba=new FormatConvertedBitmap(image,PixelFormats.Bgra32,null,0);var data=new byte[rgba.PixelWidth*rgba.PixelHeight*4];rgba.CopyPixels(data,rgba.PixelWidth*4,0);for(int i=3;i<data.Length;i+=4)if(data[i]!=255)return "当前后端不接透明输入";return (string?)null;},token);
 }
