  try{
   if(_filmTaskBridge is null)return await GenerateViewingFilmCoreAsync(source,engineId,filmId,seed,request.Token,requestedSettings);
   request.Token.ThrowIfCancellationRequested();Guid? result=null;await _filmTaskBridge.RunAsync("胶片渲染 · 固定变体",async(context,taskToken)=>{using var linked=CancellationTokenSource.CreateLinkedTokenSource(request.Token,taskToken);await context.SafeBoundaryAsync("验证固定源变体",0,cancellationToken:linked.Token);result=await GenerateViewingFilmCoreAsync(source,engineId,filmId,seed,linked.Token,requestedSettings);return new RAWSelectionAssistant.Core.Models.TaskResultSummary(1,result is null?0:1,0,0,result is null?1:0,0,0,0);},inputSnapshot:$"target:{source.TargetId}\nvariant:{source.VariantId}\nsource-sha256:{source.SourceHash}\nbackend:{engineId}",cancellationToken:CancellationToken.None);return result;
  }finally{if(ReferenceEquals(filmRequestCancellation,request))filmRequestCancellation=null;filmRequestPending=false;}
 }
